/**
 * lib/brand-icons.ts — Aurum Vault
 * Data logo brand asli (path SVG + warna hex resmi) untuk BrandIconPicker.
 * Diekstrak jadi kurasi statis di sini (bukan seluruh 3400+ brand paket asli) supaya
 * bundle app kecil — file ini murni data, tidak bergantung ke paket sumber saat
 * runtime/build. Merek dan logo tetap milik pemegang merek masing-masing.
 *
 * Sumber & lisensi per logo (komentar ini DIPERBAIKI di Tahap 5; sebelumnya menyebut
 * simple-icons "MIT" dan memetakan sumber hanya lewat `kind`). Tiap slug dicocokkan
 * dengan data path SVG paket aslinya; daftar per-slug dikunci oleh lib/attribution.ts
 * dan lib/__tests__/attribution.test.ts:
 *  - simple-icons (CC0-1.0) → `path` tunggal, satu warna. 111 logo. Enam di antaranya
 *    (openai, canva, linkedin, microsoft, microsoftoutlook, yahoo) tidak ada lagi di
 *    simple-icons 16.37.0 dan berasal dari versi lama paket itu; lisensinya tetap CC0-1.0.
 *  - Iconify "token" = Web3 Icons (MIT) → glyph crypto satu warna (`kind: "mono"`). 9 logo.
 *  - Iconify "ri" = Remix Icon (Apache-2.0) → hanya `grok` (kind "mono", BUKAN Web3 Icons).
 *  - Iconify "logos" = SVG Logos (CC0-1.0) → hanya `metamask` (kind "color", BUKAN idn-finlogos).
 *  - Iconify "arcticons" (CC BY-SA 4.0) → gambar garis (`kind: "line"`), perlu atribusi. 6 logo.
 *  - idn-finlogos 2.5.0 (CC BY-NC 4.0, nonkomersial; merek milik pemiliknya) → logo
 *    berwarna (`kind: "color"`). 27 logo.
 * Brand tanpa logo resmi sengaja TIDAK dimasukkan (tidak memakai huruf pengganti).
 */

export interface CuratedBrandIcon {
  slug:  string; // identifier unik, dipakai sebagai VaultEntry.brandIconSlug
  title: string; // nama brand untuk ditampilkan & dicari
  hex:   string; // warna ubin (6 digit tanpa #); putih untuk logo berwarna
  path:  string; // SVG path tunggal (viewBox 0 0 24 24); kosong bila memakai `body`
  body?:   string;                       // markup SVG bagian dalam (id sudah diberi awalan unik)
  vb?:     string;                       // viewBox untuk `body`
  kind?:   'mono' | 'line' | 'color';    // mono: glyph satu warna · line: gambar garis · color: logo berwarna asli
  fit?:    'mark' | 'wide' | 'full';     // color: lambang persegi · wordmark lebar · ikon aplikasi penuh
  accent?: string;                       // warna utama brand (tint kartu) bila `hex` putih
  sw?:     number;                       // tebal garis untuk kind "line", dalam satuan viewBox
}

export type BrandIconCategory =
"ai"
  | "finance"
  | "crypto"
  | "social"
  | "email"
  | "game"
  | "entertainment"
  | "shopping"
  | "travel"
  | "local"
  | "device"
  | "network"
  | "dev"
  | "cloud"
  | "security"
  | "platform";

