/** Cari brand icon berdasarkan slug. Dipakai saat render icon di EntryCard/DetailView. */
export function getBrandIconBySlug(slug: string): CuratedBrandIcon | undefined {
  return ALL_BRAND_ICONS.find((b) => b.slug === slug);
}

/** Cari brand icon berdasarkan judul/nama (case-insensitive substring), untuk search box picker. */
export function searchBrandIcons(query: string): CuratedBrandIcon[] {
  const q = query.trim().toLowerCase();
  if (!q) return ALL_BRAND_ICONS;
  return ALL_BRAND_ICONS.filter((b) => b.title.toLowerCase().includes(q) || b.slug.includes(q));
}
